CREATE OR REPLACE FUNCTION public.ops_permission(permission text,bid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_permission(permission,bid) OR EXISTS(SELECT 1 FROM public.staff_assignments s WHERE s.user_id=auth.uid() AND ((s.role='support' AND permission IN ('support.manage','operations.read','leads.manage')) OR (s.role='sales' AND permission IN ('operations.read','leads.manage'))) AND ((s.city IS NULL AND s.category IS NULL) OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=bid AND (s.city IS NULL OR s.city=b.city) AND (s.category IS NULL OR s.category=b.category)))); $$;
REVOKE ALL ON FUNCTION public.ops_permission(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ops_permission(text,uuid) TO authenticated;
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text NOT NULL UNIQUE DEFAULT ('JD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),requester_id uuid,requester_name text NOT NULL,requester_email text NOT NULL,topic text NOT NULL CHECK(topic IN ('incorrect listing','ownership','lead quality','reviews','account access','billing','general help')),description text NOT NULL CHECK(length(description) BETWEEN 10 AND 5000),business_id uuid REFERENCES public.businesses(id),lead_id uuid REFERENCES public.leads(id),claim_id uuid REFERENCES public.business_claims(id),payment_reference text NOT NULL DEFAULT '',priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')),assignee uuid,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','waiting_requester','escalated','resolved','closed')),response_due_at timestamptz,escalated_at timestamptz,resolution_reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY tickets_read ON public.support_tickets FOR SELECT TO authenticated USING(requester_id=auth.uid() OR public.ops_permission('support.manage',business_id));
CREATE TABLE public.support_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES public.support_tickets(id),actor_id uuid,kind text NOT NULL CHECK(kind IN ('reply','internal','activity')),body text NOT NULL CHECK(length(body) BETWEEN 1 AND 5000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.support_messages TO authenticated; GRANT ALL ON public.support_messages TO service_role;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_messages_read ON public.support_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.support_tickets t WHERE t.id=ticket_id AND (public.ops_permission('support.manage',t.business_id) OR (t.requester_id=auth.uid() AND kind<>'internal'))));
CREATE INDEX support_ticket_queue ON public.support_tickets(status,response_due_at,created_at);
CREATE TABLE public.buy_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requester_id uuid NOT NULL,topic text NOT NULL CHECK(length(topic) BETWEEN 3 AND 150),description text NOT NULL CHECK(length(description) BETWEEN 10 AND 3000),city text NOT NULL,category text NOT NULL,name text NOT NULL,phone text NOT NULL CHECK(phone ~ '^[6-9][0-9]{9}$'),status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','assigned','closed')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.buy_requirements TO authenticated; GRANT ALL ON public.buy_requirements TO service_role;
ALTER TABLE public.buy_requirements ENABLE ROW LEVEL SECURITY;
CREATE POLICY requirements_read ON public.buy_requirements FOR SELECT TO authenticated USING(requester_id=auth.uid() OR public.ops_permission('leads.manage'));
ALTER TABLE public.leads ADD COLUMN IF NOT EXISTS requirement_id uuid REFERENCES public.buy_requirements(id), ADD COLUMN IF NOT EXISTS assignee uuid, ADD COLUMN IF NOT EXISTS response_due_at timestamptz, ADD COLUMN IF NOT EXISTS first_response_at timestamptz, ADD COLUMN IF NOT EXISTS quotation_sent_at timestamptz, ADD COLUMN IF NOT EXISTS quotation_text text NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS outcome_reason text NOT NULL DEFAULT '';
CREATE UNIQUE INDEX lead_requirement_business_unique ON public.leads(requirement_id,business_id) WHERE requirement_id IS NOT NULL;
CREATE TABLE public.notification_preferences(user_id uuid PRIMARY KEY,in_app boolean NOT NULL DEFAULT true,email_consent boolean NOT NULL DEFAULT false,sms_consent boolean NOT NULL DEFAULT false,whatsapp_consent boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.notification_preferences TO authenticated; GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_preferences_own ON public.notification_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.in_app_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL,event_key text NOT NULL,template text NOT NULL CHECK(template IN ('lead_assigned','ticket_created','ticket_reply','lead_response')),entity_id uuid NOT NULL,business_id uuid REFERENCES public.businesses(id),title text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','attempted','sent','delivered','failed','suppressed')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 3),failure_reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),attempted_at timestamptz,sent_at timestamptz,delivered_at timestamptz,UNIQUE(event_key,recipient_id));
GRANT SELECT ON public.in_app_notifications TO authenticated; GRANT ALL ON public.in_app_notifications TO service_role;
ALTER TABLE public.in_app_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_read ON public.in_app_notifications FOR SELECT TO authenticated USING(recipient_id=auth.uid() OR public.ops_permission('operations.read',business_id));
CREATE OR REPLACE FUNCTION public.queue_in_app(recipient uuid,event_key_value text,template_value text,entity uuid,bid uuid,title_value text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.in_app_notifications(recipient_id,event_key,template,entity_id,business_id,title) VALUES(recipient,event_key_value,template_value,entity,bid,title_value) ON CONFLICT(event_key,recipient_id) DO NOTHING; $$;
REVOKE ALL ON FUNCTION public.queue_in_app(uuid,text,text,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.create_support_ticket(payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.support_tickets; bid uuid:=nullif(payload->>'business_id','')::uuid; lid uuid:=nullif(payload->>'lead_id','')::uuid; cid uuid:=nullif(payload->>'claim_id','')::uuid; BEGIN
IF length(trim(payload->>'name')) NOT BETWEEN 2 AND 150 OR length(payload->>'email')>254 OR payload->>'email' !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'A valid name and email are required'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(lower(payload->>'email'))); IF (SELECT count(*) FROM public.support_tickets WHERE lower(requester_email)=lower(payload->>'email') AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Please wait before sending another support request'; END IF;
IF bid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND (status='approved' OR owner_id=auth.uid() OR public.ops_permission('support.manage',id))) THEN RAISE EXCEPTION 'Linked business unavailable'; END IF;
IF lid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.leads l JOIN public.businesses b ON b.id=l.business_id WHERE l.id=lid AND (b.owner_id=auth.uid() OR public.ops_permission('leads.manage',b.id))) THEN RAISE EXCEPTION 'Linked lead unavailable'; END IF;
IF cid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_claims WHERE id=cid AND (claimant_id=auth.uid() OR public.ops_permission('support.manage',business_id))) THEN RAISE EXCEPTION 'Linked claim unavailable'; END IF;
INSERT INTO public.support_tickets(requester_id,requester_name,requester_email,topic,description,business_id,lead_id,claim_id,payment_reference) VALUES(auth.uid(),trim(payload->>'name'),lower(trim(payload->>'email')),payload->>'topic',trim(payload->>'description'),bid,lid,cid,left(coalesce(payload->>'payment_reference',''),150)) RETURNING * INTO t;
INSERT INTO public.support_messages(ticket_id,actor_id,kind,body) VALUES(t.id,auth.uid(),'activity','Ticket created');
IF auth.uid() IS NOT NULL THEN PERFORM public.queue_in_app(auth.uid(),'ticket-created:'||t.id,'ticket_created',t.id,bid,'Support request saved: '||t.reference); END IF;
RETURN jsonb_build_object('id',t.id,'reference',t.reference); END; $$;
REVOKE ALL ON FUNCTION public.create_support_ticket(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_support_ticket(jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.support_ticket_action(ticket uuid,action_payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.support_tickets; staff boolean; msg_id uuid; p text:=action_payload->>'action'; BEGIN SELECT * INTO t FROM public.support_tickets WHERE id=ticket FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Ticket unavailable'; END IF; staff:=public.ops_permission('support.manage',t.business_id); IF NOT staff AND t.requester_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Ticket access denied'; END IF;
IF p IN ('reply','internal') THEN IF p='internal' AND NOT staff THEN RAISE EXCEPTION 'Internal notes are staff only'; END IF; IF length(trim(action_payload->>'body')) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Write a message'; END IF;
INSERT INTO public.support_messages(ticket_id,actor_id,kind,body) VALUES(ticket,auth.uid(),p,trim(action_payload->>'body')) RETURNING id INTO msg_id;
IF p='reply' AND staff AND t.requester_id IS NOT NULL AND t.requester_id<>auth.uid() THEN PERFORM public.queue_in_app(t.requester_id,'ticket-reply:'||msg_id,'ticket_reply',ticket,t.business_id,'New reply on '||t.reference); END IF;
UPDATE public.support_tickets SET updated_at=now() WHERE id=ticket;
ELSIF p='update' THEN IF NOT staff THEN RAISE EXCEPTION 'Staff permission required'; END IF;
IF action_payload->>'status' IN ('resolved','closed') AND length(trim(action_payload->>'reason'))<5 THEN RAISE EXCEPTION 'A resolution reason is required'; END IF;
IF nullif(action_payload->>'assignee','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_assignments s WHERE s.user_id=(action_payload->>'assignee')::uuid AND s.role IN ('support','super_admin') AND (s.city IS NULL AND s.category IS NULL OR EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=t.business_id AND (s.city IS NULL OR s.city=b.city) AND (s.category IS NULL OR s.category=b.category)))) THEN RAISE EXCEPTION 'Choose an eligible support staff member'; END IF;
UPDATE public.support_tickets SET status=action_payload->>'status',priority=action_payload->>'priority',assignee=nullif(action_payload->>'assignee','')::uuid,response_due_at=nullif(action_payload->>'deadline','')::timestamptz,resolution_reason=coalesce(action_payload->>'reason',''),escalated_at=CASE WHEN action_payload->>'status'='escalated' THEN coalesce(escalated_at,now()) ELSE escalated_at END,updated_at=now() WHERE id=ticket;
INSERT INTO public.support_messages(ticket_id,actor_id,kind,body) VALUES(ticket,auth.uid(),'activity','Status: '||(action_payload->>'status')||'; priority: '||(action_payload->>'priority')||CASE WHEN action_payload->>'status' IN ('resolved','closed') THEN '; resolution: '||(action_payload->>'reason') ELSE '' END);
INSERT INTO public.support_messages(ticket_id,actor_id,kind,body) VALUES(ticket,auth.uid(),'internal','Assignment/deadline updated. '||coalesce(action_payload->>'reason',''));
ELSE RAISE EXCEPTION 'Unknown ticket action'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.support_ticket_action(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.support_ticket_action(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_buy_requirement(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to post a requirement'; END IF; IF length(trim(payload->>'name')) NOT BETWEEN 2 AND 100 OR NOT EXISTS(SELECT 1 FROM public.directory_locations WHERE kind='city' AND active AND name=payload->>'city') OR NOT EXISTS(SELECT 1 FROM public.directory_categories WHERE active AND public_visible AND (slug=payload->>'category' OR legacy_slug=payload->>'category')) THEN RAISE EXCEPTION 'Choose a valid name, city and category'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF (SELECT count(*) FROM public.buy_requirements WHERE requester_id=auth.uid() AND created_at>now()-interval '1 hour')>=5 THEN RAISE EXCEPTION 'Please wait before posting another requirement'; END IF;
INSERT INTO public.buy_requirements(requester_id,topic,description,city,category,name,phone) VALUES(auth.uid(),trim(payload->>'topic'),trim(payload->>'description'),payload->>'city',payload->>'category',trim(payload->>'name'),payload->>'phone') RETURNING id INTO rid; RETURN rid; END; $$;
REVOKE ALL ON FUNCTION public.create_buy_requirement(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_buy_requirement(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.assign_requirement(rid uuid,bid uuid,staff_id uuid,deadline timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.buy_requirements; b public.businesses; lid uuid; BEGIN SELECT * INTO b FROM public.businesses WHERE id=bid; SELECT * INTO r FROM public.buy_requirements WHERE id=rid FOR UPDATE; IF b.id IS NULL OR r.id IS NULL OR NOT public.ops_permission('leads.manage',bid) THEN RAISE EXCEPTION 'Assignment denied'; END IF; IF b.status<>'approved' OR b.city<>r.city OR b.category<>r.category THEN RAISE EXCEPTION 'Choose an approved business in the same city and category'; END IF; IF staff_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_assignments WHERE user_id=staff_id AND role IN ('support','sales','super_admin') AND (city IS NULL OR city=b.city) AND (category IS NULL OR category=b.category)) THEN RAISE EXCEPTION 'Assignee is outside this scope'; END IF;
INSERT INTO public.leads(business_id,requirement_id,name,phone,message,assignee,response_due_at) VALUES(bid,rid,r.name,r.phone,r.topic||': '||r.description,staff_id,deadline) ON CONFLICT(requirement_id,business_id) WHERE requirement_id IS NOT NULL DO UPDATE SET assignee=excluded.assignee,response_due_at=excluded.response_due_at RETURNING id INTO lid;
UPDATE public.buy_requirements SET status='assigned' WHERE id=rid; RETURN lid; END; $$;
REVOKE ALL ON FUNCTION public.assign_requirement(uuid,uuid,uuid,timestamptz) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.assign_requirement(uuid,uuid,uuid,timestamptz) TO authenticated;
CREATE OR REPLACE FUNCTION public.lead_operations_action(lid uuid,payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.leads; b public.businesses; staff boolean; a text:=payload->>'action'; BEGIN SELECT * INTO l FROM public.leads WHERE id=lid FOR UPDATE; SELECT * INTO b FROM public.businesses WHERE id=l.business_id; staff:=public.ops_permission('leads.manage',b.id); IF l.id IS NULL OR (b.owner_id IS DISTINCT FROM auth.uid() AND NOT staff) THEN RAISE EXCEPTION 'Lead access denied'; END IF;
IF a='assign' THEN IF NOT staff THEN RAISE EXCEPTION 'Staff permission required'; END IF; IF nullif(payload->>'assignee','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.staff_assignments WHERE user_id=(payload->>'assignee')::uuid AND role IN ('support','sales','super_admin') AND (city IS NULL OR city=b.city) AND (category IS NULL OR category=b.category)) THEN RAISE EXCEPTION 'Assignee outside this scope'; END IF; UPDATE public.leads SET assignee=nullif(payload->>'assignee','')::uuid,response_due_at=nullif(payload->>'deadline','')::timestamptz WHERE id=lid;
ELSIF a='response' THEN IF length(trim(payload->>'body'))<5 THEN RAISE EXCEPTION 'Describe the response'; END IF; UPDATE public.leads SET first_response_at=coalesce(first_response_at,now()),status='contacted' WHERE id=lid;
ELSIF a='quote' THEN IF length(trim(payload->>'body')) NOT BETWEEN 5 AND 3000 THEN RAISE EXCEPTION 'Describe the quotation shared with the customer'; END IF; UPDATE public.leads SET quotation_sent_at=now(),quotation_text=trim(payload->>'body') WHERE id=lid;
ELSIF a='outcome' THEN IF payload->>'status' NOT IN ('won','lost') OR length(trim(payload->>'body')) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'Choose won/lost and explain the reported outcome'; END IF; UPDATE public.leads SET status=payload->>'status',outcome_reason=trim(payload->>'body') WHERE id=lid;
ELSE RAISE EXCEPTION 'Unknown lead action'; END IF;
INSERT INTO public.directory_audit(business_id,entity_id,action,actor_id,note) VALUES(b.id,lid,'lead.'||a,auth.uid(),CASE WHEN a='assign' THEN 'Assignment/deadline updated' ELSE left(payload->>'body',3000) END); END; $$;
REVOKE ALL ON FUNCTION public.lead_operations_action(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.lead_operations_action(uuid,jsonb) TO authenticated;
CREATE POLICY operations_leads_read ON public.leads FOR SELECT TO authenticated USING(public.ops_permission('leads.manage',business_id));
CREATE OR REPLACE FUNCTION public.process_in_app_notification(nid uuid,mark_read boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n public.in_app_notifications; BEGIN SELECT * INTO n FROM public.in_app_notifications WHERE id=nid FOR UPDATE; IF n.id IS NULL OR (n.recipient_id IS DISTINCT FROM auth.uid() AND NOT public.ops_permission('operations.read',n.business_id)) THEN RAISE EXCEPTION 'Notification unavailable'; END IF;
IF mark_read THEN IF n.recipient_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the recipient can mark this read'; END IF; IF n.status='sent' THEN UPDATE public.in_app_notifications SET status='delivered',delivered_at=now() WHERE id=nid; RETURN 'delivered'; END IF; RETURN n.status; END IF;
IF n.status NOT IN ('queued','failed') OR n.attempts>=3 THEN RETURN n.status; END IF;
UPDATE public.in_app_notifications SET status='attempted',attempts=attempts+1,attempted_at=now() WHERE id=nid;
IF EXISTS(SELECT 1 FROM public.notification_preferences WHERE user_id=n.recipient_id AND NOT in_app) THEN UPDATE public.in_app_notifications SET status='suppressed',failure_reason='In-app notifications disabled by recipient' WHERE id=nid; RETURN 'suppressed'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=n.recipient_id) THEN UPDATE public.in_app_notifications SET status='failed',failure_reason='Recipient account unavailable' WHERE id=nid; RETURN 'failed'; END IF;
UPDATE public.in_app_notifications SET status='sent',sent_at=now(),failure_reason='' WHERE id=nid; RETURN 'sent'; END; $$;
REVOKE ALL ON FUNCTION public.process_in_app_notification(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.process_in_app_notification(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.notify_new_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid; BEGIN SELECT owner_id INTO uid FROM public.businesses WHERE id=NEW.business_id; IF uid IS NOT NULL THEN PERFORM public.queue_in_app(uid,'lead-created:'||NEW.id,'lead_assigned',NEW.id,NEW.business_id,'New customer enquiry'); END IF; RETURN NEW; END; $$;
CREATE TRIGGER lead_in_app_notification AFTER INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.notify_new_lead();